// Public EV charging stations in Mongolia for the homepage map and counts. Data: src/data/chargers.json,
// generated by scripts/chargers/import-evmashin.mjs from evmashin.com (replaces the made-up "50 / 5",
// user 2026-11-20). Live availability stays on evmashin.com; the page links there.
import data from "./chargers.json";

export type ChargerStation = {
  name: string; address: string; lat: number; lng: number;
  /** Number of DC (fast) and AC connectors, and the highest power of each kind in kW. */
  dc: number; dcKw: number; ac: number; acKw: number;
  plugs: string[];
};

export const CHARGER_SOURCE: { name: string; url: string; date: string } = data.source;
export const CHARGER_STATIONS: ChargerStation[] = data.stations;

/** Ulaanbaatar and around (the airport is ~30 km south): within 50 km of the centre. */
const UB = { lat: 47.918, lng: 106.917 };
const km = (a: { lat: number; lng: number }, b: { lat: number; lng: number }) => {
  const r = Math.PI / 180;
  const x = (b.lng - a.lng) * r * Math.cos(((a.lat + b.lat) / 2) * r), y = (b.lat - a.lat) * r;
  return Math.sqrt(x * x + y * y) * 6371;
};
export const UB_STATIONS = CHARGER_STATIONS.filter((station) => km(station, UB) <= 50);

/** Counts for the homepage: connectors (charge points) and places, Ulaanbaatar area only. */
export const UB_CHARGER_COUNTS = {
  places: UB_STATIONS.length,
  dc: UB_STATIONS.reduce((sum, s) => sum + s.dc, 0),
  ac: UB_STATIONS.reduce((sum, s) => sum + s.ac, 0)
};

/** "2026-08-24" → "2026.08" for the source note. */
export const chargerDataMonth = () => CHARGER_SOURCE.date.slice(0, 7).replace("-", ".");
